import java.util.*;

public class Main {
    static final int MOD = 1_000_000_007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long N = sc.nextLong();
        int K = sc.nextInt();
        sc.close();

        // Get all distinct floor(N / i) values
        List<Long> vals = new ArrayList<>();
        for (long i = 1; i <= N; ) {
            long q = N / i;
            long last = N / q;
            vals.add(q);
            i = last + 1;
        }
        Collections.reverse(vals); // increasing order
        int m = vals.size();

        // size of each group
        long[] size = new long[m];
        long prev = 0;
        for (int i = 0; i < m; i++) {
            long v = vals.get(i);
            size[i] = (N / v) - prev;
            prev = N / v;
        }

        // Build transition matrix T
        long[][] T = new long[m][m];
        long[] prefixSum = new long[m + 1];
        for (int i = 0; i < m; i++) {
            prefixSum[i + 1] = (prefixSum[i] + size[i]) % MOD;
        }
        for (int i = 0; i < m; i++) {
            // from group i, can go to any group j with vals[j] <= vals[i]
            for (int j = 0; j < m; j++) {
                if (vals.get(j) <= vals.get(i)) {
                    T[i][j] = size[j] % MOD;
                }
            }
        }

        // Initial vector: count of sequences of length 1
        long[] dp = new long[m];
        for (int i = 0; i < m; i++) {
            dp[i] = size[i] % MOD;
        }

        // Fast exponentiation: T^(K-1) * dp
        long[][] resultMat = matrixPow(T, K - 1);
        long[] finalDp = multiplyMatVec(resultMat, dp);

        long ans = 0;
        for (long v : finalDp) ans = (ans + v) % MOD;
        System.out.println(ans);
    }

    static long[][] matrixPow(long[][] mat, int exp) {
        int n = mat.length;
        long[][] res = identity(n);
        long[][] base = mat;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = multiply(res, base);
            }
            base = multiply(base, base);
            exp >>= 1;
        }
        return res;
    }

    static long[][] identity(int n) {
        long[][] I = new long[n][n];
        for (int i = 0; i < n; i++) I[i][i] = 1;
        return I;
    }

    static long[][] multiply(long[][] A, long[][] B) {
        int n = A.length;
        long[][] C = new long[n][n];
        for (int i = 0; i < n; i++) {
            for (int k = 0; k < n; k++) {
                if (A[i][k] == 0) continue;
                for (int j = 0; j < n; j++) {
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD;
                }
            }
        }
        return C;
    }

    static long[] multiplyMatVec(long[][] mat, long[] vec) {
        int n = mat.length;
        long[] res = new long[n];
        for (int i = 0; i < n; i++) {
            long sum = 0;
            for (int j = 0; j < n; j++) {
                sum = (sum + mat[i][j] * vec[j]) % MOD;
            }
            res[i] = sum;
        }
        return res;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        long N = fs.nextLong();
        int K = (int) fs.nextLong();

        // Distinct values of floor(N / x)
        ArrayList<Long> vals = new ArrayList<>();
        for (long l = 1; l <= N; ) {
            long v = N / l;
            long r = N / v;
            vals.add(v);
            l = r + 1;
        }

        // We need them in increasing order
        Collections.reverse(vals);
        int m = vals.size();

        long[] a = new long[m + 1]; // 1-indexed
        for (int i = 1; i <= m; i++) a[i] = vals.get(i - 1);

        // w[i] = count of x such that floor(N/x) == a[i]
        long[] w = new long[m + 1];
        for (int i = 1; i <= m; i++) {
            long prev = (i == 1 ? 0 : a[i - 1]);
            w[i] = N / a[i] - N / prevSafe(prev);
        }

        // Actually easier/safer using interval lengths:
        // values are increasing; corresponding x interval for value v is [L..R] where R = N/v, L = previous R + 1
        long[] cnt = new long[m + 1];
        long prevR = 0;
        for (int i = 1; i <= m; i++) {
            long R = N / a[i];
            cnt[i] = R - prevR;
            prevR = R;
        }

        // dp[i]: number of valid sequences of current length ending with any x such that floor(N/x) == a[i], per actual ending value aggregated
        long[] dp = new long[m + 1];
        for (int i = 1; i <= m; i++) dp[i] = cnt[i] % MOD; // length 1

        for (int step = 2; step <= K; step++) {
            long[] pref = new long[m + 1];
            for (int i = 1; i <= m; i++) {
                pref[i] = pref[i - 1] + dp[i];
                if (pref[i] >= MOD) pref[i] -= MOD;
            }

            long[] ndp = new long[m + 1];
            for (int i = 1; i <= m; i++) {
                // If current last element y is in class i, previous element x must satisfy x <= floor(N / y).
                // For all y in this class, floor(N / y) = a[i], which corresponds to first t classes of actual values <= a[i].
                int t = upperBound(a, a[i]); // last index with a[idx] <= a[i]
                ndp[i] = (cnt[i] % MOD) * pref[t] % MOD;
            }
            dp = ndp;
        }

        long ans = 0;
        for (int i = 1; i <= m; i++) {
            ans += dp[i];
            if (ans >= MOD) ans -= MOD;
        }
        System.out.println(ans % MOD);
    }

    static long prevSafe(long x) {
        return x == 0 ? Long.MAX_VALUE : x;
    }

    // returns last index in 1-indexed sorted array a with a[idx] <= x
    static int upperBound(long[] a, long x) {
        int l = 1, r = a.length - 1, ans = 0;
        while (l <= r) {
            int mid = (l + r) >>> 1;
            if (a[mid] <= x) {
                ans = mid;
                l = mid + 1;
            } else {
                r = mid - 1;
            }
        }
        return ans;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

