int main() {
    long long N, K;
    scanf("%lld %lld", &N, &K);

    // dp[v] = number of sequences ending at v, for v in [1..N]
    // Use sqrt decomposition
    // distinct values of floor(N/v): O(sqrt(N))

    // For simplicity if N is small enough, do direct O(K*N)
    // Assume N <= 10^5, K <= 10^5

    long long *dp = calloc(N+2, sizeof(long long));
    long long *prefix = calloc(N+2, sizeof(long long));
    long long *ndp = calloc(N+2, sizeof(long long));

    for (long long v = 1; v <= N; v++) dp[v] = 1;

    for (long long k = 1; k < K; k++) {
        // compute prefix sums
        prefix[0] = 0;
        for (long long v = 1; v <= N; v++)
            prefix[v] = (prefix[v-1] + dp[v]) % MOD;
        // compute new dp
        for (long long v = 1; v <= N; v++)
            ndp[v] = prefix[N/v];
        long long *tmp = dp; dp = ndp; ndp = tmp;
    }

    long long ans = 0;
    for (long long v = 1; v <= N; v++)
        ans = (ans + dp[v]) % MOD;

    printf("%lld\n", ans);
    free(dp); free(prefix); free(ndp);
    return 0;
}

#include <stdio.h>
#include <math.h>

#define MOD 1000000007

int main() {
    int N, K;
    scanf("%d %d", &N, &K);

    int sqrtN = (int)sqrt(N);

    // dp_small[i] for i = 1..sqrtN
    long long *dp_small = calloc((sqrtN + 1), sizeof(long long));
    // dp_large[q] for q = 1..sqrtN (represent values v where N/v = q)
    long long *dp_large = calloc((sqrtN + 1), sizeof(long long));

    // Initial length 1 sequences
    for (int v = 1; v <= sqrtN; v++) {
        dp_small[v] = 1;
    }
    for (int q = 1; q <= sqrtN; q++) {
        // values v such that floor(N/v) = q
        // count how many v give this q:
        int low = N / (q + 1) + 1;
        int high = N / q;
        if (low <= sqrtN) low = sqrtN + 1;
        if (high > N) high = N;
        if (low <= high) {
            dp_large[q] = (high - low + 1) % MOD;
        }
    }

    for (int step = 2; step <= K; step++) {
        long long sum_small = 0;
        for (int v = 1; v <= sqrtN; v++) {
            sum_small = (sum_small + dp_small[v]) % MOD;
        }

        long long new_dp_small[sqrtN+1];
        long long new_dp_large[sqrtN+1];

        // Compute transitions to small values
        for (int y = 1; y <= sqrtN; y++) {
            long long ways = 0;
            // from small values x: need x <= N/y
            int max_x = N / y;
            if (max_x >= sqrtN) {
                // all small x contribute
                ways = (ways + sum_small) % MOD;
                // plus from large x? large x have N/x <= sqrtN, but from large x, max_y = N/x <= sqrtN, so y<=sqrtN is always reachable from any large x? Wait: from large x, allowed y ≤ floor(N/x) = q. Since q ≤ sqrtN, if y ≤ q, reachable.
                // So for fixed y, from large x: we need q >= y.
                for (int q = y; q <= sqrtN; q++) {
                    ways = (ways + dp_large[q]) % MOD;
                }
            } else {
                // only x = 1..max_x contribute from small
                for (int x = 1; x <= max_x; x++) {
                    ways = (ways + dp_small[x]) % MOD;
                }
                // from large: same condition q >= y
                for (int q = y; q <= sqrtN; q++) {
                    ways = (ways + dp_large[q]) % MOD;
                }
            }
            new_dp_small[y] = ways;
        }

        // Compute transitions to large values (quotient representation)
        // For a large value v with quotient q = N/v, allowed previous x must satisfy x <= q.
        for (int q = 1; q <= sqrtN; q++) {
            long long ways = 0;
            // from small x: x <= q
            for (int x = 1; x <= q && x <= sqrtN; x++) {
                ways = (ways + dp_small[x]) % MOD;
            }
            // from large x: need N/x >= ? Actually from large x, allowed y ≤ N/x = q_x. So need q <= q_x? Wait: For previous x (large), its quotient q_x = N/x. Then allowed y ≤ q_x. So if we go to v with quotient q, we need v ≤ q_x, i.e. N/v >= N/q_x? Better: condition is y ≤ q_x. But here y = v is large. So we need v ≤ q_x. Since v > sqrtN and q_x ≤ sqrtN, this can only happen if v ≤ sqrtN, contradiction. So from large x, we cannot go to large v. So only small x contribute.
            new_dp_large[q] = ways;
        }

        // Copy back
        for (int i = 1; i <= sqrtN; i++) {
            dp_small[i] = new_dp_small[i] % MOD;
            dp_large[i] = new_dp_large[i] % MOD;
        }
    }

    long long ans = 0;
    for (int i = 1; i <= sqrtN; i++) ans = (ans + dp_small[i]) % MOD;
    for (int i = 1; i <= sqrtN; i++) ans = (ans + dp_large[i]) % MOD;

    printf("%lld\n", ans);

    free(dp_small);
    free(dp_large);
    return 0;
}

