#define MOD 1000000007LL

static inline long long addmod(long long a, long long b) {
    a += b;
    if (a >= MOD) a -= MOD;
    return a;
}

int main(void) {
    long long N;
    int K;
    if (scanf("%lld %d", &N, &K) != 2) return 0;

    int n = (int)N;

    /* dp_prev[x] = number of valid sequences of current length ending with x */
    long long *dp_prev = (long long*)malloc((n + 1) * sizeof(long long));
    long long *dp_cur  = (long long*)malloc((n + 1) * sizeof(long long));
    long long *diff    = (long long*)malloc((n + 2) * sizeof(long long));

    if (!dp_prev || !dp_cur || !diff) return 0;

    /* Length 1: any positive integer from 1..N */
    for (int i = 1; i <= n; i++) dp_prev[i] = 1;

    for (int len = 2; len <= K; len++) {
        for (int i = 0; i <= n + 1; i++) diff[i] = 0;

        /*
           Transition:
           dp_cur[y] = sum(dp_prev[x]) for all x such that x*y <= N
                     = sum over x of dp_prev[x] added to all y in [1, N/x]

           Use difference array for range additions.
        */
        for (int x = 1; x <= n; x++) {
            int r = n / x;
            long long v = dp_prev[x];
            diff[1] = addmod(diff[1], v);
            diff[r + 1] -= v;
            if (diff[r + 1] < 0) diff[r + 1] += MOD;
        }

        long long run = 0;
        for (int y = 1; y <= n; y++) {
            run += diff[y];
            if (run >= MOD) run -= MOD;
            dp_cur[y] = run;
        }

        long long *tmp = dp_prev;
        dp_prev = dp_cur;
        dp_cur = tmp;
    }

    long long ans = 0;
    for (int i = 1; i <= n; i++) {
        ans += dp_prev[i];
        if (ans >= MOD) ans -= MOD;
    }

    printf("%lld\n", ans);

    free(dp_prev);
    free(dp_cur);
    free(diff);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
const int MOD = 1e9+7;

using Matrix = vector<vector<int>>;

Matrix mul(const Matrix &a, const Matrix &b) {
    int n = a.size();
    Matrix res(n, vector<int>(n, 0));
    for (int i = 0; i < n; i++) {
        for (int k = 0; k < n; k++) {
            if (a[i][k] == 0) continue;
            for (int j = 0; j < n; j++) {
                res[i][j] = (res[i][j] + (int64)a[i][k] * b[k][j]) % MOD;
            }
        }
    }
    return res;
}

Matrix pow_mat(Matrix a, int64 e) {
    int n = a.size();
    Matrix res(n, vector<int>(n, 0));
    for (int i = 0; i < n; i++) res[i][i] = 1;
    while (e) {
        if (e & 1) res = mul(res, a);
        a = mul(a, a);
        e >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 N, K;
    cin >> N >> K;

    vector<int64> vals;
    for (int64 i = 1; i * i <= N; i++) {
        vals.push_back(i);
        if (i != N / i) vals.push_back(N / i);
    }
    sort(vals.begin(), vals.end());
    int m = vals.size();

    // transition matrix T where T[i][j] = 1 if vals[i] * vals[j] <= N
    Matrix T(m, vector<int>(m, 0));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < m; j++) {
            if (vals[i] * vals[j] <= N) {
                T[i][j] = 1;
            }
        }
    }

    Matrix Tpow = pow_mat(T, K - 1);

    // initial vector: count of sequences of length 1 ending with each value
    // For each group, count how many original numbers map to it.
    vector<int> init(m, 0);
    for (int i = 0; i < m; i++) {
        int64 low = (i == 0 ? 1 : vals[i-1] + 1);
        int64 high = vals[i];
        init[i] = (high - low + 1) % MOD;
    }

    // result = init * Tpow
    vector<int> res(m, 0);
    for (int j = 0; j < m; j++) {
        for (int i = 0; i < m; i++) {
            res[j] = (res[j] + (int64)init[i] * Tpow[i][j]) % MOD;
        }
    }

    int ans = 0;
    for (int x : res) ans = (ans + x) % MOD;
    cout << ans << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int MOD = 1e9 + 7;

int main(){
    long long N, K;
    cin >> N >> K;

    // Get all distinct values of floor(N/v)
    vector<long long> vals;
    for(long long v = 1, nv; v <= N; v = nv + 1){
        long long q = N / v;
        nv = N / q;
        vals.push_back(q);
    }
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());

    // g[m] = prefix sum up to m, only stored for relevant m values
    // Use map
    map<long long, long long> g;
    // Base: g(m, 1) = m (number of values from 1 to m)
    for(auto m : vals) g[m] = m % MOD;

    for(int k = 2; k <= K; k++){
        map<long long, long long> ng;
        for(auto m : vals){
            // g(m, k) = sum_{v=1}^{m} g(floor(N/v), k-1)
            long long res = 0;
            for(long long v = 1, nv; v <= m; v = nv + 1){
                long long q = N / v;
                nv = N / q;
                long long cnt = min(nv, m) - v + 1;
                res = (res + cnt % MOD * g[q]) % MOD;
            }
            ng[m] = res;
        }
        g = ng;
    }

    cout << g[N] << endl;
}

#include <bits/stdc++.h>
using namespace std;

static const int MOD = 1000000007;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long N;
    int K;
    cin >> N >> K;

    // dp[x] = number of sequences of current length ending with value x
    // Transition:
    // new_dp[y] = sum(dp[x]) for all x such that x * y <= N
    //           = prefix[floor(N / y)]
    //
    // Since values are positive integers and if some element > N,
    // then it cannot have any adjacent positive integer (because product >= element > N).
    // For K >= 2, all elements must be in [1..N].
    // For K == 1, answer is infinite unless domain is [1..N].
    // Standard interpretation here is elements are in [1..N].

    vector<int> dp(N + 1, 1), ndp(N + 1), pref(N + 1);

    if (K == 1) {
        cout << (N % MOD) << '\n';
        return 0;
    }

    for (int len = 2; len <= K; ++len) {
        pref[0] = 0;
        for (int i = 1; i <= N; ++i) {
            pref[i] = pref[i - 1] + dp[i];
            if (pref[i] >= MOD) pref[i] -= MOD;
        }

        for (long long y = 1; y <= N; ++y) {
            ndp[y] = pref[N / y];
        }

        dp.swap(ndp);
    }

    long long ans = 0;
    for (int i = 1; i <= N; ++i) {
        ans += dp[i];
        if (ans >= MOD) ans -= MOD;
    }

    cout << ans % MOD << '\n';
    return 0;
}
